  1→"use client";
  2→
  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { EllipsisVertical, Plus } from "lucide-react";
 17→import type { AgentStatus } from "@/lib/types";
 18→import type { AgentClientState } from "@/hooks/use-websocket";
 19→import { cn } from "@/lib/utils";
 20→
 21→/** Status dot color + optional pulse animation. */
 22→const STATUS_DOT: Record<AgentStatus, string> = {
 23→  idle: "bg-muted-foreground",
 24→  spawning: "bg-yellow-500 animate-pulse",
 25→  connected: "bg-green-500",
 26→  thinking: "bg-blue-500 animate-pulse",
 27→  done: "bg-muted-foreground",
 28→  disconnected: "bg-orange-500 animate-pulse",
 29→  error: "bg-red-500",
 30→};
 31→
 32→/** Statuses where the CLI is actively running and can be killed. */
 33→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 34→/** Statuses considered archived (session ended, read-only). */
 35→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 36→
 37→interface ContextMenuState {
 38→  agentId: string;
 39→  x: number;
 40→  y: number;
 41→}
 42→
 43→export function AgentSidebar({
 44→  agents,
 45→  agentOrder,
 46→  activeAgentId,
 47→  loading,
 48→  onSelect,
 49→  onNewAgent,
 50→  onKill,
 51→  onDelete,
 52→  onRename,
 53→  onClearHistory,
 54→}: {
 55→  agents: Map<string, AgentClientState>;
 56→  agentOrder: string[];
 57→  activeAgentId: string | null;
 58→  loading?: boolean;
 59→  onSelect: (agentId: string | null) => void;
 60→  onNewAgent: () => void;
 61→  onKill: (agentId: string) => void;
 62→  onDelete: (agentId: string) => void;
 63→  onRename: (agentId: string, label: string) => void;
 64→  onClearHistory: (agentId: string) => void;
 65→}) {
 66→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 67→  const [renamingId, setRenamingId] = useState<string | null>(null);
 68→  const menuRef = useRef<HTMLDivElement>(null);
 69→
 70→  // Split agents into active and archived
 71→  const activeIds = agentOrder.filter((id) => {
 72→    const a = agents.get(id);
 73→    return a && !ARCHIVED.has(a.status);
 74→  });
 75→  const archivedIds = agentOrder.filter((id) => {
 76→    const a = agents.get(id);
 77→    return a && ARCHIVED.has(a.status);
 78→  });
 79→
 80→  // Close context menu on click-outside or Escape
 81→  useEffect(() => {
 82→    if (!ctxMenu) return;
 83→    function handleClick(e: MouseEvent) {
 84→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
 85→        setCtxMenu(null);
 86→      }
 87→    }
 88→    function handleKey(e: KeyboardEvent) {
 89→      if (e.key === "Escape") setCtxMenu(null);
 90→    }
 91→    document.addEventListener("mousedown", handleClick);
 92→    document.addEventListener("keydown", handleKey);
 93→    return () => {
 94→      document.removeEventListener("mousedown", handleClick);
 95→      document.removeEventListener("keydown", handleKey);
 96→    };
 97→  }, [ctxMenu]);
 98→
 99→  const openMenu = useCallback((agentId: string, x: number, y: number) => {
100→    setCtxMenu({ agentId, x, y });
101→  }, []);
102→
103→  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
104→    e.preventDefault();
105→    openMenu(agentId, e.clientX, e.clientY);
106→  }, [openMenu]);
107→
108→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
109→    e.stopPropagation();
110→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
111→    openMenu(agentId, rect.right, rect.bottom);
112→  }, [openMenu]);
113→
114→  const closeMenu = useCallback(() => setCtxMenu(null), []);
115→
116→  function renderAgentRow(id: string, archived: boolean) {
117→    const agent = agents.get(id);
118→    if (!agent) return null;
119→    const isActive = id === activeAgentId;
120→    return (
121→      <div
122→        key={id}
123→        onClick={() => onSelect(id)}
124→        onContextMenu={(e) => handleContextMenu(e, id)}
125→        className={cn(
126→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
127→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
128→          archived && "opacity-60"
129→        )}
130→      >
131→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
132→          <span className="flex items-center gap-2">
133→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
134→            {renamingId === id ? (
135→              <RenameInput
136→                initialValue={agent.label}
137→                onConfirm={(label) => {
138→                  onRename(id, label);
139→                  setRenamingId(null);
140→                }}
141→                onCancel={() => setRenamingId(null)}
142→              />
143→            ) : (
144→              <span className="truncate">{agent.label || "new agent"}</span>
145→            )}
146→          </span>
147→          {agent.tmuxSession && (
148→            <span className="pl-4 text-[10px] text-muted-foreground truncate">
149→              {agent.tmuxSession}
150→            </span>
151→          )}
152→        </div>
153→        <button
154→          onClick={(e) => handleMenuButton(e, id)}
155→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
156→          aria-label="Agent menu"
157→        >
158→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
159→        </button>
160→      </div>
161→    );
162→  }
163→
164→  return (
165→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
166→      {/* Branding */}
167→      <div className="flex items-center gap-2 border-b px-3 py-2">
168→        <span className="text-primary font-bold text-sm tracking-tight">thos</span>
169→        <span className="text-muted-foreground text-[10px]">orchestrator</span>
170→      </div>
171→
172→      {/* Header */}
173→      <div className="flex items-center justify-between px-3 py-2">
174→        <span className="text-xs font-semibold">agents</span>
175→        <button
176→          onClick={onNewAgent}
177→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
178→          aria-label="New agent"
179→        >
180→          <Plus className="size-3.5" />
181→        </button>
182→      </div>
183→
184→      {/* Agent list */}
185→      <div className="flex-1 overflow-y-auto">
186→        {loading ? (
187→          <div className="space-y-1 px-3 py-2">
188→            {[...Array(4)].map((_, i) => (
189→              <div key={i} className="flex items-center gap-2 py-2">
190→                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
191→                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
192→              </div>
193→            ))}
194→          </div>
195→        ) : agentOrder.length === 0 ? (
196→          <div className="px-3 py-4 text-xs text-muted-foreground">
197→            No agents yet
198→          </div>
199→        ) : null}
200→
201→        {/* Active agents */}
202→        {activeIds.map((id) => renderAgentRow(id, false))}
203→
204→        {/* Archived divider + agents */}
205→        {archivedIds.length > 0 && (
206→          <>
207→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
208→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
209→              <div className="flex-1 border-t" />
210→            </div>
211→            {archivedIds.map((id) => renderAgentRow(id, true))}
212→          </>
213→        )}
214→      </div>
215→
216→      {/* Context menu */}
217→      {ctxMenu && (() => {
218→        const agent = agents.get(ctxMenu.agentId);
219→        if (!agent) return null;
220→        return (
221→          <div
222→            ref={menuRef}
223→            className="fixed z-50 min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
224→            style={{ left: ctxMenu.x, top: ctxMenu.y }}
225→          >
226→            <ContextMenuItem
227→              label="Rename"
228→              onClick={() => {
229→                setRenamingId(ctxMenu.agentId);
230→                closeMenu();
231→              }}
232→            />
233→            {KILLABLE.has(agent.status) && (
234→              <ContextMenuItem
235→                label="Kill"
236→                onClick={() => {
237→                  onKill(ctxMenu.agentId);
238→                  closeMenu();
239→                }}
240→              />
241→            )}
242→            <ContextMenuItem
243→              label="Clear History"
244→              onClick={() => {
245→                onClearHistory(ctxMenu.agentId);
246→                closeMenu();
247→              }}
248→            />
249→            <div className="my-1 border-t" />
250→            <ContextMenuItem
251→              label="Delete"
252→              destructive
253→              onClick={() => {
254→                closeMenu();
255→                if (confirm("Delete this agent? This cannot be undone.")) {
256→                  onDelete(ctxMenu.agentId);
257→                }
258→              }}
259→            />
260→          </div>
261→        );
262→      })()}
263→    </div>
264→  );
265→}
266→
267→/** A single item in the context menu. */
268→function ContextMenuItem({
269→  label,
270→  onClick,
271→  destructive,
272→}: {
273→  label: string;
274→  onClick: () => void;
275→  destructive?: boolean;
276→}) {
277→  return (
278→    <button
279→      onClick={onClick}
280→      className={cn(
281→        "flex w-full px-3 py-1.5 text-xs transition-colors",
282→        destructive
283→          ? "text-red-500 hover:bg-red-500/10"
284→          : "hover:bg-accent"
285→      )}
286→    >
287→      {label}
288→    </button>
289→  );
290→}
291→
292→/** Inline input for renaming an agent. */
293→function RenameInput({
294→  initialValue,
295→  onConfirm,
296→  onCancel,
297→}: {
298→  initialValue: string;
299→  onConfirm: (value: string) => void;
300→  onCancel: () => void;
301→}) {
302→  const [value, setValue] = useState(initialValue);
303→  const inputRef = useRef<HTMLInputElement>(null);
304→
305→  useEffect(() => {
306→    inputRef.current?.focus();
307→    inputRef.current?.select();
308→  }, []);
309→
310→  function handleKeyDown(e: React.KeyboardEvent) {
311→    e.stopPropagation();
312→    if (e.key === "Enter") {
313→      const trimmed = value.trim();
314→      if (trimmed) onConfirm(trimmed);
315→      else onCancel();
316→    } else if (e.key === "Escape") {
317→      onCancel();
318→    }
319→  }
320→
321→  return (
322→    <input
323→      ref={inputRef}
324→      type="text"
325→      value={value}
326→      onChange={(e) => setValue(e.target.value)}
327→      onKeyDown={handleKeyDown}
328→      onBlur={() => {
329→        const trimmed = value.trim();
330→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
331→        else onCancel();
332→      }}
333→      onClick={(e) => e.stopPropagation()}
334→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
335→    />
336→  );
337→}
