 17→/** Format a timestamp as a relative string like "just now", "2m ago", "1h ago". */
 18→function formatRelativeTime(ts: number): string {
 19→  const diff = Date.now() - ts;
 20→  if (diff < 60_000) return "just now";
 21→  const mins = Math.floor(diff / 60_000);
 22→  if (mins < 60) return `${mins}m ago`;
 23→  const hrs = Math.floor(mins / 60);
 24→  if (hrs < 24) return `${hrs}h ago`;
 25→  const days = Math.floor(hrs / 24);
 26→  return `${days}d ago`;
 27→}
 28→
 29→/** Timestamp showing "12:34 PM (2m ago)" that updates every 30s. */
 30→function MessageTime({ timestamp, className }: { timestamp: number; className?: string }) {
 31→  const [, setTick] = useState(0);
 32→
 33→  useEffect(() => {
 34→    const id = setInterval(() => setTick((t) => t + 1), 30_000);
 35→    return () => clearInterval(id);
 36→  }, []);
 37→
 38→  const absolute = new Date(timestamp).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
 39→  const relative = formatRelativeTime(timestamp);
 40→
 41→  return (
 42→    <time
 43→      dateTime={new Date(timestamp).toISOString()}
 44→      title={new Date(timestamp).toLocaleString()}
 45→      className={className}
 46→    >
 47→      {absolute} ({relative})
 48→    </time>
 49→  );
 50→}
