 18→/** Format a tool name for display: strip namespace prefixes, convert to title. */
 19→function formatToolName(name: string): string {
 20→  // e.g. "Bash" stays "Bash", "mcp__something__tool" → "tool"
 21→  const parts = name.split("__");
 22→  return parts[parts.length - 1];
 23→}
