 25→/** Render a single input value, truncating long strings. */
 26→function InputValue({ value }: { value: unknown }) {
 27→  if (value === null || value === undefined) {
 28→    return <span className="text-muted-foreground italic">null</span>;
 29→  }
 30→  if (typeof value === "boolean") {
 31→    return <span className="text-blue-400">{String(value)}</span>;
 32→  }
 33→  if (typeof value === "number") {
 34→    return <span className="text-blue-400">{value}</span>;
 35→  }
 36→  if (typeof value === "string") {
 37→    // For long strings (file contents, code, commands), show in a code block
 38→    if (value.includes("\n") || value.length > 120) {
 39→      return (
 40→        <pre className="mt-1 max-h-60 overflow-auto rounded bg-black/30 p-2 text-xs leading-relaxed whitespace-pre-wrap break-all">
 41→          {value}
 42→        </pre>
 43→      );
 44→    }
 45→    return (
 46→      <code className="rounded bg-black/20 px-1.5 py-0.5 text-xs break-all">
 47→        {value}
 48→      </code>
 49→    );
 50→  }
 51→  // Objects / arrays — JSON dump
 52→  return (
 53→    <pre className="mt-1 max-h-40 overflow-auto rounded bg-black/30 p-2 text-xs leading-relaxed">
 54→      {JSON.stringify(value, null, 2)}
 55→    </pre>
 56→  );
