 59→export function ControlRequest({
 60→  message,
 61→  onRespond,
 62→}: {
 63→  message: ChatMessage;
 64→  onRespond: (requestId: string, allow: boolean) => void;
 65→}) {
 66→  const cr = message.controlRequest;
 67→  if (!cr) return null;
 68→
 69→  // Capture stable reference for inner closure (strict mode narrowing)
 70→  const requestId = cr.id;
 71→
 72→  const [respondedWith, setRespondedWith] = useState<
 73→    "allowed" | "denied" | null
 74→  >(null);
 75→
 76→  const resolved = cr.resolved || respondedWith !== null;
 77→  const displayName = formatToolName(cr.tool_name);
 78→  const entries = Object.entries(cr.input);
 79→
 80→  function handleRespond(allow: boolean) {
 81→    setRespondedWith(allow ? "allowed" : "denied");
 82→    onRespond(requestId, allow);
 83→  }
 84→
 85→  return (
 86→    <div
 87→      className={cn(
 88→        "w-full max-w-2xl rounded-lg border p-4",
 89→        resolved
 90→          ? "border-muted-foreground/15 bg-secondary/50"
 91→          : "border-primary/30 bg-secondary"
 92→      )}
 93→    >
 94→      {/* Header */}
 95→      <div className="mb-3 flex items-center gap-2">
 96→        <ShieldAlert
 97→          className={cn(
 98→            "h-4 w-4 shrink-0",
 99→            resolved ? "text-muted-foreground" : "text-primary"
100→          )}
101→        />
102→        <span className="text-xs font-medium text-muted-foreground">
103→          Tool approval
104→        </span>
105→        <span className="text-sm font-semibold">{displayName}</span>
106→        {cr.tool_name !== displayName && (
107→          <span className="text-xs text-muted-foreground">
108→            ({cr.tool_name})
109→          </span>
110→        )}
111→      </div>
112→
113→      {/* Description */}
114→      {cr.description && (
115→        <p className="mb-3 text-sm text-muted-foreground">{cr.description}</p>
116→      )}
117→
118→      {/* Input parameters */}
119→      {entries.length > 0 && (
120→        <div className="mb-4 space-y-2">
121→          {entries.map(([key, value]) => (
122→            <div key={key}>
123→              <div className="text-xs font-medium text-muted-foreground">
124→                {key}
125→              </div>
126→              <div className="mt-0.5 text-sm">
127→                <InputValue value={value} />
128→              </div>
129→            </div>
130→          ))}
131→        </div>
132→      )}
133→
134→      {/* Actions / Status */}
135→      {!resolved ? (
136→        <div className="flex gap-2">
137→          <Button size="sm" onClick={() => handleRespond(true)}>
138→            <Check className="mr-1 h-3.5 w-3.5" />
139→            Allow
140→          </Button>
141→          <Button
142→            size="sm"
143→            variant="outline"
144→            onClick={() => handleRespond(false)}
145→          >
146→            <X className="mr-1 h-3.5 w-3.5" />
147→            Deny
148→          </Button>
149→        </div>
150→      ) : (
151→        <div
152→          className={cn(
153→            "inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium",
154→            respondedWith === "denied"
155→              ? "bg-destructive/15 text-destructive"
156→              : "bg-primary/15 text-primary"
157→          )}
158→        >
159→          {respondedWith === "denied" ? (
160→            <>
161→              <X className="h-3 w-3" /> Denied
162→            </>
163→          ) : (
164→            <>
165→              <Check className="h-3 w-3" /> Allowed
166→            </>
167→          )}
168→        </div>
169→      )}
170→    </div>
171→  );
172→}
