240→
241→      <div className="mt-2 flex items-center justify-between">
242→        <button
243→          className={cn(
244→            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
245→            STATUS_COLORS[task.status]
